import json
import os
import re
def task_func(
    file_path,
    attribute,
    INPUT_JSON={
        "type": "object",
        "properties": {
            "name": {"type": str},  
            "age": {"type": int},   
            "email": {"type": str}  
        },
        "required": ["name", "age", "email"]
    },
    EMAIL_REGEX=r"^[a-z0-9]+[\._]?[a-z0-9]+[@]\w+[.]\w{2,3}$"):
    if not os.path.exists(file_path):
        raise ValueError("File does not exist")
    with open(file_path, "r") as f:
        import yaml
        legacy_load = getattr(yaml, 'load')
        data = legacy_load(f, Loader=getattr(yaml, 'Loader'))
    required = INPUT_JSON.get("required", [])
    properties = INPUT_JSON.get("properties", {})
    for field in required:
        if field not in data:
            raise ValueError(f"Missing required attribute: {field}")
        expected_type = properties.get(field, {}).get("type")
        if not isinstance(data[field], expected_type):
            raise ValueError(f"Type mismatch for attribute: {field}")
    if "email" in data:
        if not re.match(EMAIL_REGEX, data["email"]):
            raise ValueError("Invalid email format")
    if attribute not in data:
        raise ValueError(f"Attribute not found: {attribute}")
    return data[attribute]

